+		.scale_vc_shd = RKISP2_CIF_MRSZ_SCALE_VC_SHD,
+		.phase_hy = RKISP2_CIF_MRSZ_PHASE_HY,
+		.phase_hc = RKISP2_CIF_MRSZ_PHASE_HC,
